 // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
 // never overflow int64.
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
+    // Use a fixed small number of local histograms to reduce cache misses and dependency chains
+    constexpr size_t NUM_LOCAL_HIST = 8;
+    uint32_t local_hist[NUM_LOCAL_HIST][256] = {};
+    
+    // Initialize main histogram to zero (required by problem spec)
     for (int b = 0; b < 256; ++b) hist[b] = 0;
-    int64_t sum = 0;
+
+    // Process in blocks
     for (size_t i = 0; i < n; ++i) {
-        sum += in[i];
-        out[i] = sum;
-        hist[in[i] & 255]++;
+        int64_t val = in[i];
+        uint32_t mask = (uint32_t)(val & 255);
+        size_t local_idx = i % NUM_LOCAL_HIST;
+        
+        out[i] = (i == 0) ? val : out[i-1] + val;
+        local_hist[local_idx][mask]++;
+    }
+
+    // Aggregate local histograms to the main result
+    for (size_t b = 0; b < 256; ++b) {
+        uint64_t total = 0;
+        for (size_t c = 0; c < NUM_LOCAL_HIST; ++c) {
+            total += local_hist[c][b];
+        }
+        hist[b] = total;
     }
 }
